struct anim_vtable {
    char pad0[24];
    short flag_adjustment;
    short pad1;
    void (*set_flag_fn)(void *, int, bool);
    short time_adjustment;
    short pad2;
    void (*set_time_fn)(void *, float);
};

class entity_anim_tree {
    char pad0[4];
    anim_vtable *vtable;
    char pad1[88];
    unsigned flags;
public:
    void set_suspended(bool suspended) {
        if (suspended)
            flags |= 0x40;
        else
            flags &= ~0x40;
    }
    void set_flag(int flag, bool value) {
        anim_vtable *table = vtable;
        table->set_flag_fn((char *)this + table->flag_adjustment, flag, value);
    }
    void set_time(float time) {
        anim_vtable *table = vtable;
        table->set_time_fn((char *)this + table->time_adjustment, time);
    }
};

class world_dynamics_system {
public:
    float get_scene_anim_time(unsigned handle);
    unsigned play_scene_anim(const stringx &, bool reverse, float time);
    entity_anim_tree *get_scene_anim_tree(unsigned handle);
    void kill_scene_anim(unsigned handle);
};

